package e2b

import (
	"net/url"
	"strconv"
	"strings"

	"github.com/agent-sandbox/agent-sandbox/pkg/api/e2b/api"
)

// GetV2SandboxesParams is generated from the e2b OpenAPI description and declares
// metadata, state, nextToken and limit on GET /v2/sandboxes. Nothing bound them to
// the request, so every query was answered with the caller's full sandbox list.
//
// These helpers parse and apply exactly those four, matching the contract the
// generated type documents.

// parseListParams reads the declared query parameters off the request.
//
// state is an array in the OpenAPI description. Both encodings real clients emit
// are accepted: repeated (state=running&state=paused) and comma-separated
// (state=running,paused).
//
// An unparseable limit, nextToken, or an unknown state is reported rather than
// ignored: the contract says these are typed, and silently discarding a filter the
// caller asked for is how an unfiltered response gets mistaken for an empty one.
func parseListParams(q url.Values) (*api.GetV2SandboxesParams, string) {
	p := &api.GetV2SandboxesParams{}

	if raw, ok := q["metadata"]; ok && len(raw) > 0 && raw[0] != "" {
		v := raw[0]
		p.Metadata = &v
	}

	if raw, ok := q["state"]; ok {
		var states []api.SandboxState
		for _, item := range raw {
			for _, part := range strings.Split(item, ",") {
				part = strings.TrimSpace(part)
				if part == "" {
					continue
				}
				st := api.SandboxState(part)
				if !st.Valid() {
					return nil, "invalid state: " + part
				}
				states = append(states, st)
			}
		}
		if len(states) > 0 {
			p.State = &states
		}
	}

	if raw := strings.TrimSpace(q.Get("limit")); raw != "" {
		n, err := strconv.ParseInt(raw, 10, 32)
		if err != nil || n < 1 {
			return nil, "invalid limit: " + raw
		}
		limit := api.PaginationLimit(n)
		p.Limit = &limit
	}

	if raw := strings.TrimSpace(q.Get("nextToken")); raw != "" {
		if n, err := strconv.Atoi(raw); err != nil || n < 0 {
			return nil, "invalid nextToken: " + raw
		}
		tok := api.PaginationNextToken(raw)
		p.NextToken = <REDACTED>
	}

	return p, ""
}

// parseMetadataFilter decodes the metadata query into key/value pairs.
//
// The generated type documents the format as `user=abc&app=prod` with each key and
// value URL encoded, so the value arrives double-encoded: once for the pair and once
// for the surrounding query string. net/url has already undone the outer layer by the
// time this sees it, so exactly one decode remains.
//
// A malformed filter returns ok=false and the caller answers 400. It must never
// degrade to "no filter" - a caller asking for a workspace that does not exist has to
// get an empty list, never somebody else's sandboxes.
func parseMetadataFilter(raw string) (map[string]string, bool) {
	if raw == "" {
		return nil, true
	}
	out := map[string]string{}
	for _, pair := range strings.Split(raw, "&") {
		if pair == "" {
			continue
		}
		k, v, found := strings.Cut(pair, "=")
		if !found || k == "" {
			return nil, false
		}
		dk, err := url.QueryUnescape(k)
		if err != nil {
			return nil, false
		}
		dv, err := url.QueryUnescape(v)
		if err != nil {
			return nil, false
		}
		out[dk] = dv
	}
	return out, true
}

// metadataMatches reports whether every requested pair is present on the sandbox.
// Subset semantics, matching e2b: a sandbox carrying extra keys still matches.
func metadataMatches(sbxMeta map[string]string, want map[string]string) bool {
	for k, v := range want {
		got, ok := sbxMeta[k]
		if !ok || got != v {
			return false
		}
	}
	return true
}

// stateMatches reports whether the sandbox is in one of the requested states.
func stateMatches(state api.SandboxState, want []api.SandboxState) bool {
	for _, w := range want {
		if state == w {
			return true
		}
	}
	return false
}

// applyListFilters filters, then pages. Order matters: limit has to apply to what
// survived filtering, or a limit could hide the very rows a filter selected.
//
// nextToken is a plain index cursor here. It is opaque to clients by contract, and
// the list is already sorted CreatedAt-descending by the controller, so an index is
// stable enough for paging a single caller's sandboxes. Returns the page and the
// token for the next one ("" when the page is the last).
func applyListFilters(in []*api.Sandbox, p *api.GetV2SandboxesParams, meta map[string]string) ([]*api.Sandbox, string) {
	out := make([]*api.Sandbox, 0, len(in))
	for _, sbx := range in {
		if len(meta) > 0 && !metadataMatches(sbx.Metadata, meta) {
			continue
		}
		if p.State != nil && !stateMatches(sbx.State, *p.State) {
			continue
		}
		out = append(out, sbx)
	}

	start := 0
	if p.NextToken != nil {
		// Already validated as a non-negative integer by parseListParams.
		start, _ = strconv.Atoi(string(*p.NextToken))
	}
	if start >= len(out) {
		return []*api.Sandbox{}, ""
	}
	out = out[start:]

	if p.Limit != nil && int(*p.Limit) < len(out) {
		next := strconv.Itoa(start + int(*p.Limit))
		return out[:*p.Limit], next
	}
	return out, ""
}

# E2B Sandbox Networking Reference

## Public URLs

Every sandbox has a public URL for accessing services running inside it. The port is the leftmost part of the hostname.

```typescript
const host = sandbox.getHost(3000)
// → "3000-i62mff4ahtrdfdkyn2esc.e2b.app"
const url = `https://${host}`
```

```python
host = sandbox.get_host(3000)
url = f'https://{host}'
```

## Internet Access Control

By default, sandboxes have full internet access. Disable with `allowInternetAccess: false` / `allow_internet_access=False`.

```typescript
// No internet
const sandbox = await Sandbox.create({ allowInternetAccess: false })
```

```python
sandbox = Sandbox.create(allow_internet_access=False)
```

Setting `allowInternetAccess` to `false` is equivalent to `network.denyOut: ['0.0.0.0/0']`.

## Fine-Grained Network Control

Use `network` config for allow/deny lists with IPs, CIDRs, or domains.

```typescript
import { Sandbox, ALL_TRAFFIC } from '@e2b/code-interpreter'

// Deny all, allow specific IPs
const sandbox = await Sandbox.create({
  network: {
    denyOut: [ALL_TRAFFIC],
    allowOut: ['1.1.1.1', '8.8.8.0/24'],
  },
})
```

```python
from e2b_code_interpreter import Sandbox, ALL_TRAFFIC

sandbox = Sandbox.create(
    network={
        "deny_out": [ALL_TRAFFIC],
        "allow_out": ["1.1.1.1", "8.8.8.0/24"],
    },
)
```

### Domain-Based Filtering

Allow traffic to specific domains. Must use `ALL_TRAFFIC` in deny list. Wildcards supported.

```typescript
const sandbox = await Sandbox.create({
  network: {
    allowOut: ['api.example.com', '*.github.com'],
    denyOut: [ALL_TRAFFIC],
  },
})
```

```python
sandbox = Sandbox.create(
    network={
        "allow_out": ["api.example.com", "*.github.com"],
        "deny_out": [ALL_TRAFFIC],
    },
)
```

**Limitations:** Domain filtering works for HTTP (port 80, Host header) and TLS (port 443, SNI). Other ports use CIDR only. UDP/QUIC/HTTP3 not supported for domain filtering. DNS nameserver `8.8.8.8` is auto-allowed when domains are used.

### Priority Rules

**Allow rules always take precedence** over deny rules. If an IP is in both lists, it is allowed.

### ALL_TRAFFIC Constant

`ALL_TRAFFIC` = `'0.0.0.0/0'` — matches all IP addresses.

## Restricting Public Access (Traffic Access Token)

By default sandbox URLs are publicly accessible. Restrict with `allowPublicTraffic: false`.

```typescript
const sandbox = await Sandbox.create({
  network: { allowPublicTraffic: false },
})

// Get the access token
console.log(sandbox.trafficAccessToken)

// Unauthenticated request → 403
const response1 = await fetch(url)

// Authenticated request → 200
const response2 = await fetch(url, {
  headers: { 'e2b-traffic-access-token': sandbox.trafficAccessToken },
})
```

```python
sandbox = Sandbox.create(
    network={"allow_public_traffic": False},
)

print(sandbox.traffic_access_token)

# Authenticated request
response = requests.get(url, headers={
    'e2b-traffic-access-token': sandbox.traffic_access_token,
})
```

## Host Masking

Customize the `Host` header sent to services inside the sandbox.

```typescript
const sandbox = await Sandbox.create({
  network: { maskRequestHost: 'localhost:${PORT}' },
})
// Requests will have Host: localhost:8080 (for port 8080)
```

```python
sandbox = Sandbox.create(
    network={"mask_request_host": "localhost:${PORT}"},
)
```

The `${PORT}` variable is replaced with the actual port number.

