type Controller struct {
	kclient       kubernetes.Interface
	MetricsClient *metrics.Clientset
	kcfg          *rest.Config
	rootCtx       context.Context
	pl            *PoolManager
	recorder      record.EventRecorder
}

func NewController(ctx context.Context, cfg *rest.Config, pl *PoolManager, recorder record.EventRecorder) *Controller {
	c := kubeclient.Get(ctx)
	sh := &Controller{
		rootCtx:  ctx,
		kclient:  c,
		kcfg:     cfg,
		pl:       pl,
		recorder: recorder,
	}
	return sh
}

func (s *Controller) GetRSByID(id string) (*v1.ReplicaSet, error) {
	selector := labels.Set{IDLabel: id, PoolLabel: "false"}.AsSelector()
	rss, err := rsclient.Get(s.rootCtx).Lister().ReplicaSets(config.Cfg.SandboxNamespace).List(selector)
	if err != nil {
		klog.Errorf("Failed to list rs, id %s error %v", id, err)
		return nil, err
	}
	if len(rss) == 0 {
		klog.Warningf("No rs found with id %s", id)
		return nil, fmt.Errorf("no rs found with id %s", id)
	}
	return rss[0], nil
}

func (s *Controller) GetByID(id string) (*Sandbox, error) {
	rs, err := s.GetRSByID(id)
	if err != nil {
		return nil, err
	}
	return s.GetSandbox(rs)
}

func (s *Controller) Get(name string) (*Sandbox, error) {
	selector, _ := labels.Parse(fmt.Sprintf("sandbox=%s", name))
	rss, err := rsclient.Get(s.rootCtx).Lister().ReplicaSets(config.Cfg.SandboxNamespace).List(selector)
	if err != nil {
		return nil, err
	}

	if len(rss) == 0 {
		return nil, fmt.Errorf("no Sandbox found with name %s", name)
	}

	return s.GetSandbox(rss[0])
}

func (s *Controller) GetSandbox(rs *v1.ReplicaSet) (*Sandbox, error) {
	raw := rs.Annotations[AnnotationSandboxData]
	processSnapshotRaw := rs.Annotations[AnnotationProcessSnapshot]
	sb := &Sandbox{}
	json.Unmarshal([]byte(raw), sb)
	sb.ReplicaSet = rs.DeepCopy()
	sb.Status = deriveSandboxStatus(rs)
	if sb.Metadata == nil {
		sb.Metadata = map[string]string{}
	}
	if processSnapshotRaw != "" {
		sb.Metadata["snapshot"] = processSnapshotRaw
	}

	return sb, nil
}

func deriveSandboxStatus(rs *v1.ReplicaSet) SandboxState {
	replicas := int32(0)
	if rs.Spec.Replicas != nil {
		replicas = *rs.Spec.Replicas
	}
	if rs.Annotations[AnnotationPaused] == "true" && replicas == 0 {
		return Paused
	}
	// Support resume without pause,
	// in case the sandbox pod is deleted by some accident operation e.g. eviction,
	// and user want to resume  by before call Sandbox Snapshot.
	if rs.Annotations[AnnotationProcessSnapshot] != "" && replicas == 0 {
		return Paused
	}
	if replicas > 0 && replicas == rs.Status.ReadyReplicas {
		return Running
	}
	return Creating
}

func (s *Controller) ListPoolByNames(names []string) ([]*Sandbox, error) {
	selectorString := fmt.Sprintf("%s=true,%s in (%s)", PoolLabel, TPLLabel, strings.Join(names, ","))
	selector, _ := labels.Parse(selectorString)

	return s.DoList(selector)
}

